(async()=>{const browser=await chromium.launch({headless:true,args:['--no-sandbox']});const context=await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});const coach=await context.newPage(),rpc=[];context.on('request',r=>{if(/\/rest\/v1\/rpc\//.test(r.url()))rpc.push(r.url())});try{await coach.goto(BASE,{waitUntil:'domcontentloaded'});const popupPromise=context.waitForEvent('page');await coach.evaluate(p=>{window.__previewPayload=p;window.addEventListener('message',e=>{if(e.origin!==location.origin||e.data?.type!=='msos-swimmer-preview-ready')return;e.source.postMessage({type:'msos-swimmer-preview-payload',payload:window.__previewPayload},location.origin);});window.open(new URL('swimmer-portal.html?coachPreview=1',location.href).toString(),'preview-test');},payload);const popup=await popupPromise;await popup.waitForSelector('[data-sp-preview-banner]',{timeout:5000});assert.equal(await popup.locator('h1').first().innerText(),'Matthew');assert.match(await popup.locator('.sp-session').innerText(),/2026-08-15/);assert.match(await popup.locator('.sp-session').innerText(),/Old session preview/);assert.match(await popup.locator('.sp-session').innerText(),/1,200m/);assert.match(await popup.locator('.sp-session').innerText(),/6 x 100 Free Threshold/);assert.match(await popup.locator('.sp-session').innerText(),/Target 1:10 · leave 1:20/);assert.equal(await popup.locator('[data-tab="meet"]').count(),0,'shelved/empty Meet must not clutter swimmer portal');assert.equal(await popup.locator('[data-challenge]').count(),2);assert.equal(await popup.locator('[data-edit]').count(),2);assert.equal(await popup.locator('[data-finish-session]').count(),1);assert.match(await popup.locator('.sp-history').innerText(),/PAST SESSIONS/);assert.match(await popup.locator('.sp-history').innerText(),/Attended at AquaGym/);assert.match(await popup.locator('.sp-history').innerText(),/Completed remotely/);assert.match(await popup.locator('.sp-history').innerText(),/2026-08-12/);assert.match(await popup.locator('.sp-history').innerText(),/2026-08-20/);assert.equal(await popup.locator('.sp-history [data-challenge]').count(),0,'past sessions must be read-only');assert.equal(await popup.locator('.sp-history [data-edit]').count(),0,'past sessions must be read-only');const hist=popup.locator('.sp-history-session');await hist.nth(0).click();assert.match(await hist.nth(0).innerText(),/Remote completion/);assert.match(await hist.nth(0).innerText(),/RPE 7/);assert.match(await hist.nth(0).innerText(),/Held targets/);await hist.nth(1).click();assert.match(await hist.nth(1).innerText(),/5 x 100 Free/);assert.equal(rpc.length,0,'coach preview must make zero swimmer RPC calls');assert.equal(await popup.evaluate(()=>localStorage.getItem('msos_swimmer_device_token_v1')),null,'preview must not store a device token');await popup.locator('[data-challenge]').first().click();await popup.waitForSelector('.sp-modal');await popup.locator('.sp-modal [data-save]').click();await popup.waitForFunction(()=>document.querySelector('.sp-modal [data-status]')?.textContent?.includes('read-only'));assert.equal(rpc.length,0,'preview Challenge must not write');await popup.locator('.sp-modal [data-cancel]').click();await popup.locator('[data-tab="performance"]').click();assert.match(await popup.locator('#portal').innerText(),/100 Butterfly/);assert.match(await popup.locator('#portal').innerText(),/410 WA/);await popup.locator('[data-tab="training"]').click();assert.match(await popup.locator('#portal').innerText(),/8,200m/);await popup.locator('[data-tab="tests"]').click();assert.match(await popup.locator('#portal').innerText(),/Freestyle T400/);assert.equal(rpc.length,0);console.log('SWIMMER_PORTAL_COACH_PREVIEW_PASS same-renderer latest-plus-roll-and-remote-history read-only no-device-token no-rpc');}finally{await browser.close();}})().catch(e=>{console.error(e.stack||e);process.exit(1)});
